PYTHON_NODE = 'py@127.0.0.1'
ELIXIR_NODE_NAME = 'uex'
ELIXIR_NODE_HOST = '127.0.0.1'
PYTHON_REGISTERED_NAME = 'py_side'
ELIXIR_REGISTERED_NAME = 'ta_UExGate_interface'
COOKIE = "XDXD"

bg_logger = BackgroundLogger()


class Receiver(Process):
    def __init__(self, node, queue):
        Process.__init__(self)
        self.node = node
        self.queue = queue
        node.register_name(self, Atom(PYTHON_REGISTERED_NAME))

    def handle_one_inbox_message(self, msg):
        """Handle one inbox message"""
        self.queue.put(msg)


class UExInterface:
    def __init__(self, elixir_node_host=ELIXIR_NODE_HOST):
        self.node_name = PYTHON_NODE
        self.cookie_name = COOKIE
        self.elixir_node_name = '{}@{}'.format(ELIXIR_NODE_NAME, elixir_node_host)
        logging.getLogger('pyrlang.node').disabled = True

        self.node = None
        self.results_queue = None
        self._receiver = None
        self._start_node()

        self._uexgate_atoms = []
        self.is_closing = False
        self.timeout = 3600
        self._main_interface = None
        self._uex_json_rpc_client = None
        self._elixir_node_host = elixir_node_host

    def _start_node(self):
        self.node = self._get_node()
        self.results_queue = Queue()
        UexLogHandler(bg_logger)
        self._receiver = Receiver(self.node, self.results_queue)  # noqa: F841
        daemon_thread = threading.Thread(target=self.node.run)
        daemon_thread.daemon = True
        daemon_thread.start()
        # self._node_daemon_thread = daemon_thread

    def _restart_node(self):
        self.close()
        # self.node.get_loop().call_soon(lambda future: future.set_result(True), self.node._Node__completed_future)
        time.sleep(60)
        del self.node
        del self.results_queue
        del self._receiver
        time.sleep(60)
        new_ui = UExInterface(self._elixir_node_host)
        new_ui.set_2nd_interface_instance(self._uex_json_rpc_client)
        new_ui.set_main_interface(self._main_interface)
        self._main_interface._uex_interface = new_ui
        del self

    def set_2nd_interface_instance(self, uex_json_rpc_client):
        self._uex_json_rpc_client = uex_json_rpc_client

    def set_main_interface(self, interface):
        self._main_interface = interface

    def open_connection(self):
        pass

    def set_atoms_list(self):
        """Set UExGate atoms list"""
        # recovery action for LTECUSPR-437 for no response from uexgate at startup. After first timeout retry procedure
        try:
            self._uexgate_atoms = self.call_elixir_function('UExGate', 'get_atoms_list', response_timeout=30)
        except TimeoutError:  # noqa: F821
            self._uexgate_atoms = self.call_elixir_function('UExGate', 'get_atoms_list', response_timeout=30)

    def close(self):
        """Leave asyncio loop"""
        self.node.get_loop().call_soon(lambda future: future.set_result(True), self.node._Node__completed_future)
        self.node.node_db.deactivate(self.node)

    def call_uexgate_function(self, function_name, cmd_string, **cmd_kwargs):
        """
        Call function from Elixir.UExGate module
        """
        if function_name == 'execute_command_without_cli_warnings':
            module = Atom('UExGate.CLI')
            func = Atom(function_name)
            result = self.call_elixir_function(module, func, cmd_string, **cmd_kwargs)
        else:
            module = Atom('UExGate')
            function_name = re.search(r'(\S+).*', cmd_string).group(1)
            cmd_string_without_function_name = cmd_string.lstrip(function_name).strip()
            func = Atom(function_name)

            args = re.findall(r'(?:(?<= )|(?<=^))[^\s=]+(?= |$)', cmd_string_without_function_name)
            str_kwargs = re.findall(r'\S+=\S+', cmd_string_without_function_name)
            kwargs = {}
            for kw in str_kwargs:
                k = kw.split('=')[0]
                v = kw.split('=')[1]
                kwargs[k] = v

            if kwargs:
                wrapped_keyword_list = [] if kwargs == {} else [[(Atom(kk), vv) for kk, vv in kwargs.items()]]
                wrapped_keyword_list = [sort_keys_if_needed(function_name, wrapped_keyword_list[0])]
                kw_list = convert_items(wrapped_keyword_list,
                                        [(lambda item: item in map(str, self._uexgate_atoms), lambda item: Atom(item)),
                                         (lambda item: item == 'true', lambda _: True),
                                         (lambda item: item == 'false', lambda _: False),
                                         (lambda item: isinstance(item, str) and item.isdigit(), int),
                                         (lambda item: isinstance(item, str) and item.replace('.', '', 1).isdigit(),
                                          float),
                                         (lambda item: isinstance(item, str)
                                          and re.search(range_regex, item), convert_elixir_range),
                                         (lambda item: func in hex_string_cmd_to_param_names_map.keys()
                                          and isinstance(item, tuple)
                                          and item[0] in hex_string_cmd_to_param_names_map[func],
                                          lambda item: (item[0], str(item[1])))
                                         ])
                # filter_uecap_conversion(kw_list)
            else:
                kw_list = []
            if args:
                arg_list = convert_items(list(args), [
                    (lambda item: item in map(str, self._uexgate_atoms), lambda item: Atom(item))])
            else:
                arg_list = []
            arg_list = arg_list + kw_list
            result = self.call_elixir_function(module, func, *arg_list, **cmd_kwargs)

        return self._verify_uexgate_cmd_result(result)

    def call_elixir_function(self, module, function_name, *args, **kwargs):  # noqa C901
        """
        Call elixir function from specified module

        Args structure is converted in the following way:
        - Strings into bytes
        - None into nil atom

        Return value is converted in the following way:
        - Bytes into strings
        - nil atom into None

        :param module:
        :param function_name:
        :param args:
        :return:
        """
        bg_logger.log_background_messages()
        response_time = self._get_response_timeout(kwargs.pop('response_timeout', None))
        start_time = float(time.time())

        self._create_task(module, function_name, args)

        while True:
            if time.time() - start_time > response_time:
                raise TimeoutError('{}.{} failed'.format(module, function_name))  # noqa: F821
            try:
                msg = self.results_queue.get(timeout=0)
                val = self._convert_items_in_msg(msg)
                self._handle_exceptions_and_log_messages(bg_logger, val)
                return val

            except Empty:
                result = self._uex_json_rpc_client.receive_data(timeout=0.1)
                if result == 'pyrlang_node_down':
                    logging.warning("pyrlang node down")
                    try:
                        self._restart_node()
                        result = self._main_interface._uex_interface.call_elixir_function_without_retry(module, function_name, *args, **kwargs)
                        tl().update('node_down_counter', 1, {"retry_status": "passed"})
                        return result
                    except Exception:
                        tl().update('node_down_counter', 1, {"retry_status": "failed"})
                        raise
                elif result:
                    logging.warning(f'Unexpected msg received via json rpc: {result}')

    def call_elixir_function_without_retry(self, module, function_name, *args, **kwargs):  # noqa C901
        """
        Call elixir function from specified module

        Args structure is converted in the following way:
        - Strings into bytes
        - None into nil atom

        Return value is converted in the following way:
        - Bytes into strings
        - nil atom into None

        :param module:
        :param function_name:
        :param args:
        :return:
        """
        bg_logger.log_background_messages()
        response_time = self._get_response_timeout(kwargs.pop('response_timeout', None))
        self._create_task(module, function_name, args)
        try:
            msg = self.results_queue.get(timeout=response_time)
            val = self._convert_items_in_msg(msg)
            self._handle_exceptions_and_log_messages(bg_logger, val)
        except Empty:
            raise TimeoutError('{}.{} failed'.format(module, function_name))  # noqa: F821
        return val

    def _handle_exceptions_and_log_messages(self, bg_logger, val):
        if not self.is_closing:
            bg_logger.log_background_messages()
        if isinstance(val, tuple) and val[0] == Atom('exception'):
            _, exception, message, staktrace = val
            if "Elixir." in exception:
                exception = exception[7:]
            raise ElixirException("\n** ({}) {}\n{}".format(exception, message, staktrace))

    def _convert_items_in_msg(self, msg):
        val = convert_items(msg,
                            [(lambda item: (isinstance(item, str) and not isinstance(item, Atom)),
                              lambda item: [ord(elem) for elem in item]),  # charlist > regular list
                             (lambda item: isinstance(item, bytes), bytes.decode),  # decode bytes
                             (lambda item: item == Atom('nil'), lambda _: None)])  # & nil > None
        return val

    def _create_task(self, module, function_name, args):
        full_module_name = Atom('Elixir.{}'.format(module))
        func = Atom(function_name)

        if module == 'UExGate.CLI':
            cmd_string = args[0]
            self.node.get_loop().create_task(self._call_elixir_function((full_module_name, func, cmd_string)))

        else:
            converted_args = list(convert_items(
                args, [(lambda item: isinstance(item, str) and not isinstance(item, Atom), str.encode),
                       (lambda item: item is None, lambda _: Atom('nil'))
                       ]))  # encode strings & None > nil
            self.node.get_loop().create_task(self._call_elixir_function((full_module_name, func, converted_args)))

    async def _receive_and_print_data(self):
        while True:
            await asyncio.sleep(1)
            result = self._uex_json_rpc_client._receive_and_print_data(timeout=0, recurrence=False)
            if result:
                self.results_queue.put(result)
                break

    def _get_response_timeout(self, response_timeout):
        if response_timeout is not None:
            try:
                response_timeout = int(response_timeout)
                if response_timeout <= 0:
                    response_timeout = self.timeout
            except (ValueError, TypeError):  # nopep8
                response_timeout = self.timeout
        else:
            response_timeout = self.timeout
        return response_timeout

    @staticmethod
    def get_atom(data):
        return Atom(data)

    def _get_node(self):
        try:
            return Node(node_name=self.node_name, cookie=self.cookie_name)
        except RuntimeError as err:
            if str(err) == "There is no current event loop in thread 'MainThread'." \
                    and sys.version_info.major == 3 and sys.version_info.minor < 9:
                raise RuntimeError(f"asyncio exception caught:\n"
                                   f"{traceback.format_exc()}\n"
                                   f"asyncio was probably called before the 1st ta_uexgate usage.\n"
                                   f"Please use Python 3.9 (or higher) "
                                   f"or create ta_uexgate instance with flag lazy_start set to False.")
            else:
                raise

    @staticmethod
    def _verify_uexgate_cmd_result(result):
        """Checks whether the returned value is an :ok, {:ok, result} or {:error, reason}"""
        if isinstance(result, tuple) and len(result) == 2 and result[0] == Atom("ok"):
            bg_logger.info("UExGate command execution succeeded with result: {}", result[1])
            return result[1]
        elif isinstance(result, tuple) and len(result) == 2 and result[0] == Atom("error"):
            raise UExGateCommandFailure("UExGate command execution failed with reason: {}".format(result[1]))
        elif result == Atom("ok"):
            return None
        else:
            raise ValueError("invalid UExGate return value {}. Expected :ok, {{:ok, result}} or {{:error, reason}}".format(result))

    async def _call_elixir_function(self, msg):
        fake_pid = self.node.register_new_process()
        await self.node.send(sender=fake_pid,
                             receiver=(Atom(self.elixir_node_name), Atom(ELIXIR_REGISTERED_NAME)),
                             message=(Atom('rpc'), msg))


